-- Liss Leagues — migration 06
-- Multi-league fantasy support, plus the Manteno Fantasy Football League
-- (MFFL), 2011-2025. Existing rows default to EALFFL.
-- Safe to run on an existing database.

-- ---------------------------------------------------------------
-- 1. Scope the fantasy tables by league
-- ---------------------------------------------------------------
alter table ff_standings add column if not exists league text not null default 'EALFFL';
alter table ff_playoffs  add column if not exists league text not null default 'EALFFL';
alter table ff_weekly    add column if not exists league text not null default 'EALFFL';

-- Old uniqueness assumed one league. Replace with league-scoped versions.
alter table ff_standings drop constraint if exists ff_standings_season_member_key;
alter table ff_playoffs  drop constraint if exists ff_playoffs_season_round_winner_loser_key;
alter table ff_weekly    drop constraint if exists ff_weekly_season_week_member_key;

create unique index if not exists ff_standings_key on ff_standings (league, season, member);
create unique index if not exists ff_playoffs_key  on ff_playoffs (league, season, round, winner, loser);
create unique index if not exists ff_weekly_key    on ff_weekly (league, season, week, member);

create index if not exists idx_ff_standings_league on ff_standings (league);
create index if not exists idx_ff_playoffs_league  on ff_playoffs (league);
create index if not exists idx_ff_weekly_league    on ff_weekly (league);

-- ---------------------------------------------------------------
-- 2. MFFL seed data (2011-2025)
--    The 2026 season is skipped — rostered but no games played yet.
-- ---------------------------------------------------------------
insert into ff_standings
  (league, season, member, reg_rank, final_rank, team, owner, record,
   wins, losses, ties, pf, pa, pf_g, pa_g, div, home, away, strk, moves)
